class Solution:
    def minDays(self, bloomDay: list[int], m: int, k: int) -> int:
        if m * k > len(bloomDay):          # not enough flowers: no day can work
            return -1

        def bouquets(day: int) -> int:     # greedy scan: O(n)
            made = run = 0
            for d in bloomDay:
                if d <= day:
                    run += 1               # one more adjacent bloomed flower
                    if run == k:
                        made += 1          # form a bouquet and start a new run
                        run = 0
                else:
                    run = 0                # an unbloomed flower breaks adjacency
            return made

        lo, hi = min(bloomDay), max(bloomDay)   # at hi every flower has bloomed, so hi is feasible
        while lo < hi:                     # O(log(max day)) iterations
            mid = (lo + hi) // 2
            if bouquets(mid) >= m:
                hi = mid                   # feasible: try fewer days
            else:
                lo = mid + 1               # infeasible: need more days
        return lo

